// ── VoxDesk: Validate & Normalize Availability Payload ──────────────────────
const body = $input.first().json.body || $input.first().json;

// Required fields
const required = ['requested_date', 'requested_time', 'service_type'];
for (const field of required) {
  if (!body[field]) {
    throw new Error(`VALIDATION_ERROR: Missing required field: ${field}`);
  }
}

// Service duration map (minutes) — must match booking workflow
const durations = {
  'haircut': 45,
  'hair coloring': 90,
  'massage': 60,
  'facial': 60,
  'consultation': 30,
  'default': 60
};

const serviceKey = body.service_type.toLowerCase();
const durationMins = durations[serviceKey] || durations['default'];

// Parse requested datetime
const [year, month, day] = body.requested_date.split('-').map(Number);
const [hour, minute] = body.requested_time.split(':').map(Number);

const startDate = new Date(year, month - 1, day, hour, minute);
const endDate = new Date(startDate.getTime() + durationMins * 60 * 1000);

// Validate business hours (9 AM – 6 PM)
if (hour < 9 || hour >= 18) {
  // Return immediately — outside hours, no need to hit calendar
  return [{
    json: {
      available: false,
      reason: 'OUTSIDE_BUSINESS_HOURS',
      checked_slot: startDate.toISOString(),
      time_min: startDate.toISOString(),
      time_max: endDate.toISOString(),
      skip_calendar_check: true
    }
  }];
}

// Validate not in the past
if (startDate < new Date()) {
  return [{
    json: {
      available: false,
      reason: 'IN_THE_PAST',
      checked_slot: startDate.toISOString(),
      time_min: startDate.toISOString(),
      time_max: endDate.toISOString(),
      skip_calendar_check: true
    }
  }];
}

return [{
  json: {
    available: null,
    reason: null,
    checked_slot: startDate.toISOString(),
    time_min: startDate.toISOString(),
    time_max: endDate.toISOString(),
    skip_calendar_check: false
  }
}];

// ── VoxDesk: Evaluate Calendar Response ─────────────────────────────────────
const items = $input.all();
const checkedSlot = $('Code: Validate & Normalize').first().json.checked_slot;
const timeMin = $('Code: Validate & Normalize').first().json.time_min;
const timeMax = $('Code: Validate & Normalize').first().json.time_max;

// Count events that actually overlap (Google returns events by timeMin/timeMax)
const conflictingEvents = items.filter(item => {
  const event = item.json;
  // Skip cancelled/declined events
  if (event.status === 'cancelled') return false;
  // Check if attendee self-declined
  const selfAttendee = (event.attendees || []).find(a => a.self);
  if (selfAttendee && selfAttendee.responseStatus === 'declined') return false;
  return true;
});

const available = conflictingEvents.length === 0;

// Find next available slot (simple: offer +1 hour if slot is taken)
let nextAvailable = null;
if (!available) {
  const requestedStart = new Date(timeMin);
  const nextSlot = new Date(requestedStart.getTime() + 60 * 60 * 1000); // +1 hour
  // Only suggest if still within business hours (before 18:00)
  if (nextSlot.getHours() < 18) {
    nextAvailable = nextSlot.toISOString();
  }
}

return [{
  json: {
    available,
    checked_slot: checkedSlot,
    next_available: nextAvailable,
    conflict_count: conflictingEvents.length
  }
}];
